```openscad
// Flat dial ring with radial tick marks for a rotary stage
// Units: mm. Print orientation: flat on bed, top face (with ticks) up.

// ---- Ring dimensions ----
outer_d     = 70;    // outer diameter of ring
inner_d     = 50;    // inner diameter of ring
thickness   = 5;     // ring thickness (Z)

// ---- Tick mark dimensions ----
tick_count  = 36;    // number of evenly spaced ticks
tick_width  = 1.5;   // groove width (tangential)
tick_depth  = 1.5;   // groove depth from top face
tick_length = 4;     // groove length, measured inward from outer edge
start_angle = 0;     // first tick on +X axis (degrees)

// ---- Modelling helpers ----
eps         = 0.5;   // overshoot so cutters pass cleanly through faces
$fn         = 128;   // circle resolution

outer_r = outer_d / 2;
inner_r = inner_d / 2;

difference() {
    // Annulus body
    difference() {
        cylinder(h = thickness, r = outer_r);
        translate([0, 0, -eps])
            cylinder(h = thickness + 2 * eps, r = inner_r);
    }

    // Radial tick grooves in the top face
    for (i = [0 : tick_count - 1]) {
        rotate([0, 0, start_angle + i * 360 / tick_count])
            translate([outer_r - tick_length,
                       -tick_width / 2,
                       thickness - tick_depth])
                cube([tick_length + eps,
                      tick_width,
                      tick_depth + eps]);
    }
}
```

