// Flat dial ring with radial tick marks for a rotary stage
// Print orientation: flat on bed, top face (with ticks) facing up (+Z)

$fn = 128;                // resolution for curved surfaces

// ---------- Ring dimensions ----------
outer_d     = 70;         // outer diameter of annulus
inner_d     = 50;         // inner diameter of annulus
ring_t      = 4;          // ring thickness (Z)

// ---------- Tick mark dimensions ----------
tick_count  = 12;         // number of evenly spaced ticks
tick_w      = 1;          // groove width (tangential)
tick_depth  = 1;          // groove depth into top face
tick_len    = 3;          // groove length, inward from outer edge
tick_start_angle = 0;     // first tick on +X axis

// ---------- Cutting overlap ----------
eps         = 0.5;        // extension past cut faces to avoid coplanar faces

outer_r = outer_d / 2;
inner_r = inner_d / 2;

difference() {
    // Annulus body
    difference() {
        cylinder(h = ring_t, r = outer_r);
        translate([0, 0, -eps])
            cylinder(h = ring_t + 2 * eps, r = inner_r);
    }

    // Radial tick grooves in top face
    for (i = [0 : tick_count - 1]) {
        rotate([0, 0, tick_start_angle + i * 360 / tick_count])
            translate([outer_r - tick_len,
                       -tick_w / 2,
                       ring_t - tick_depth])
                cube([tick_len + eps,          // extends past outer edge
                      tick_w,
                      tick_depth + eps]);      // extends above top face
    }
}
