// Anti-vibration foot for benchtop instrument
// Frustum, printed resting on its wide base at z = 0

$fn = 128;

// --- Dimensions (mm) ---
base_d      = 50;    // frustum diameter at bottom (z = 0)
top_d       = 42;    // frustum diameter at flat top
