recess_h    = 3;     // rubber pad recess depth
screw_d     = 4.5;   // central through-hole for screw
eps         = 0.5;   // overcut for clean boolean differences

difference() {
    // Main frustum body
    cylinder(h = foot_h, d1 = base_d, d2 = top_d);

    // Rubber pad recess in bottom face
    translate([0, 0, -eps])
        cylinder(h = recess_h + eps, d = recess_d);

    // Central screw hole through the full height
    translate([0, 0, -eps])
        cylinder(h = foot_h + 2 * eps, d = screw_d);
}
