```openscad
// Stiffened cover panel
plate_len   = 120;  // plate length along X
plate_wid   = 80;   // plate width along Y
plate_thk   = 3;    // plate thickness (z = 0..3)

rib_thk     = 3;    // rib thickness along X
rib_h       = 5;    // rib height above plate (z = 3..8)
rib_count   = 3;    // number of ribs
rib_pitch   = 30;   // centre-to-centre spacing of ribs
overlap     = 0.01; // small overlap into plate for clean union

union() {
    // Base plate
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Ribs, running full width along Y
    for (i = [0 : rib_count - 1]) {
        x_c = (i - (rib_count - 1)/2) * rib_pitch;
        translate([x_c - rib_thk/2, -plate_wid/2, plate_thk - overlap])
            cube([rib_thk, plate_wid, rib_h + overlap]);
    }
}
