difference() {
    // Main block, centred in X/Y, resting on z = 0
    translate([-block_len / 2, -block_wid / 2, 0])
        cube([block_len, block_wid, block_h]);

    // Semicircular tunnels along Y, axes at z = 0, centred along X
    for (i = [0 : tunnel_n - 1]) {
        x = (i - (tunnel_n - 1) / 2) * tunnel_pitch;
        translate([x, 0, 0])
            rotate([90, 0, 0])
                cylinder(r = tunnel_r, h = block_wid + 2 * eps, center = true);
    }
}
