// Star-shaped indexing wheel (6-pointed), flat plate printed lying on the bed

// ---------------- Parameters ----------------
n_points   = 6;    // number of star points
r_outer    = 30;   // radius to outer (tip) points [mm]
r_inner    = 15;   // radius to inner (valley) points [mm]
thickness  = 3;    // plate thickness [mm]
hole_d     = 6;    // centre through-hole diameter [mm]
eps        = 0.5;  // cutter overshoot past faces [mm]
$fn        = 96;   // curve resolution

// ---------------- Star outline ----------------
// Alternating outer/inner vertices, first outer point on +X axis
function star_pts(n, ro, ri) =
    [ for (i = [0 : 2*n - 1])
        let (a = i * 180 / n,
             r = (i % 2 == 0) ? ro : ri)
        [ r * cos(a), r * sin(a) ] ];

// ---------------- Model ----------------
difference() {
    linear_extrude(height = thickness)
        polygon(star_pts(n_points, r_outer, r_inner));

    // Centre hole, extends past top and bottom faces
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = thickness + 2*eps);
}
