pocket_size  = 50;   // square pocket side length (centred in top face)
pocket_depth = 8;    // pocket depth measured down from top face
eps          = 0.5;  // overshoot for clean boolean cuts

// ---- Model ----
difference() {
    // Solid square frustum: linear_extrude with scale gives flat sloping sides
    linear_extrude(height = block_height, scale = top_size / base_size)
        square([base_size, base_size], center = true);

    // Square pocket cut into the top face
    translate([-pocket_size / 2, -pocket_size / 2, block_height - pocket_depth])
        cube([pocket_size, pocket_size, pocket_depth + eps]);
}
