x_trans = x_gauge + trans_length;        // end of transition     (30)
x_end   = x_trans + grip_length;         // end of grip / part    (60)

gw = gauge_width / 2;                    // half gauge width
pw = grip_width / 2;                     // half grip width

// Sanity check: computed length should equal total_length
assert(abs(2 * x_end - total_length) < 1e-6,
       "Section lengths do not add up to total_length");

// ---------------- Outline (top view) ----------------
outline = [
    [-x_end,   -pw], [-x_trans, -pw], [-x_gauge, -gw],
    [ x_gauge, -gw], [ x_trans, -pw], [ x_end,   -pw],
    [ x_end,    pw], [ x_trans,  pw], [ x_gauge,  gw],
    [-x_gauge,  gw], [-x_trans,  pw], [-x_end,    pw]
];

// ---------------- Model ----------------
linear_extrude(height = thickness)
    polygon(outline);
