rim_or   = rim_od / 2;
rim_ir   = rim_or - rim_width;
hub_r    = hub_d / 2;
eps      = 0.5;         // cutter overshoot
overlap  = 0.5;         // spoke overlap into hub/rim for solid union

module rim() {
    difference() {
        cylinder(h = wheel_thk, r = rim_or);
        translate([0, 0, -eps])
            cylinder(h = wheel_thk + 2*eps, r = rim_ir);
    }
}

module hub() {
    cylinder(h = wheel_thk, r = hub_r);
}

module spokes() {
    spoke_len = (rim_ir + overlap) - (hub_r - overlap);
    for (i = [0 : spoke_count - 1])
        rotate([0, 0, spoke_start_a + i * 360 / spoke_count])
            translate([hub_r - overlap, -spoke_w/2, 0])
                cube([spoke_len, spoke_w, wheel_thk]);
}

difference() {
    union() {
        rim();
        hub();
        spokes();
    }
    // axle hole
    translate([0, 0, -eps])
        cylinder(h = wheel_thk + 2*eps, d = axle_d);
}
