spoke_overlap  = 0.5;  // spoke extension into hub/rim for solid union
eps            = 0.5;  // cut overshoot past faces

$fn = 128;

// Derived
rim_id      = rim_od - 2 * rim_width;      // rim inner diameter (70)
spoke_start = hub_d / 2 - spoke_overlap;   // spoke inner end radius
spoke_end   = rim_id / 2 + spoke_overlap;  // spoke outer end radius

// ---------------- Model ----------------
difference() {
    union() {
        // Outer rim
        difference() {
            cylinder(d = rim_od, h = thickness);
            translate([0, 0, -eps])
                cylinder(d = rim_id, h = thickness + 2 * eps);
        }

        // Hub
        cylinder(d = hub_d, h = thickness);

        // Spokes, first along +X
        for (i = [0 : spoke_count - 1])
